<script setup lang="ts">import{onMounted,ref}from"vue";import{get,post}from"../api";const labels=ref<any[]>([]),name=ref("");async function load(){labels.value=await get("/labels")}async function add(){await post("/labels",{name:name.value});name.value="";load()}onMounted(load);</script><template><h1>标签管理</h1><div class="row"><input v-model="name" placeholder="标签名称"><button @click="add">新建标签</button></div><div class="panel" v-for="label in labels" :key="label.id"><span :style="{color:label.color}">●</span> {{label.name}}</div></template>
